source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    r_bounds = [-1] + rows + [h]
    c_bounds = [-1] + cols + [w]
    rb = [(r_bounds[i] + 1, r_bounds[i + 1]) for i in range(len(r_bounds) - 1)]
    cb = [(c_bounds[i] + 1, c_bounds[i + 1]) for i in range(len(c_bounds) - 1)]
    markers = {}
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            for color in colors:
                markers.setdefault(color, []).append((ri, ci))
    painted = {}
    for color, points in markers.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted.setdefault((r1, c), set()).add(color)
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted.setdefault((r, c1), set()).add(color)
    out = [row[:] for row in grid]
    for (ri, ci), colors in painted.items():
        color = 6 if 2 in colors and 3 in colors else next(iter(colors))
        r0, r1 = rb[ri]
        c0, c1 = cb[ci]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
'''
